# SIAMS-ALPHA-M1: generated by setup-alpha-apps.sh, safe to edit (re-runs skip it)
"""Shared user factories. Team Beta uses these to build users without Alpha's APIs."""

import factory
from factory.django import DjangoModelFactory

from apps.core.enums import Role

DEFAULT_PASSWORD = "Password123!"


class UserFactory(DjangoModelFactory):
    class Meta:
        model = "accounts.User"
        skip_postgeneration_save = True

    email = factory.Sequence(lambda n: f"user{n}@example.com")
    full_name = factory.Faker("name")
    role = Role.STUDENT
    is_active = True

    @factory.post_generation
    def password(self, create, extracted, **kwargs):
        self.set_password(extracted or DEFAULT_PASSWORD)
        if create:
            self.save(update_fields=["password"])


class StudentProfileFactory(DjangoModelFactory):
    class Meta:
        model = "accounts.StudentProfile"

    user = factory.SubFactory(UserFactory, role=Role.STUDENT)
    registration_number = factory.Sequence(lambda n: f"REG-{n:04d}")
    programme = "BSc Computer Science"
    year_of_study = 3


class StudentFactory(UserFactory):
    """A student with a profile (registration number)."""

    role = Role.STUDENT

    profile = factory.RelatedFactory(StudentProfileFactory, factory_related_name="user")


class WorkplaceSupervisorFactory(UserFactory):
    role = Role.WORKPLACE_SUPERVISOR


class AcademicSupervisorFactory(UserFactory):
    role = Role.ACADEMIC_SUPERVISOR


class CoordinatorFactory(UserFactory):
    role = Role.COORDINATOR
